```cpp
void cmMakefileTargetGenerator::WriteTargetBuildRules()
{
  // Evaluate generator expressions and expand prop_value
  auto evaluatedFiles = [this](std::string const& prop_value) -> cmList {
    cmList files{ cmGeneratorExpression::Evaluate(
      prop_value, this->LocalGenerator, this->GetConfigName(),
      this->GeneratorTarget) };
    return files;
  };

  // Look for additional files registered for cleaning
  auto cleanFiles = evaluatedFiles(this->Makefile->GetProperty("ADDITIONAL_MAKE_CLEAN_FILES"));
  this->CleanFiles.insert(cleanFiles.begin(), cleanFiles.end());

  auto additionalCleanFiles = evaluatedFiles(this->GeneratorTarget->GetProperty("ADDITIONAL_CLEAN_FILES"));
  for (std::string const& cfl : additionalCleanFiles) {
    this->CleanFiles.insert(cmSystemTools::CollapseFullPath(cfl, this->LocalGenerator->GetCurrentBinaryDirectory()));
  }

  // Look for ISPC extra object files generated by this target
  auto ispcAdditionalObjs = this->GeneratorTarget->GetGeneratedISPCObjects(this->GetConfigName());
  for (std::string const& ispcObj : ispcAdditionalObjs) {
    this->CleanFiles.insert(this->LocalGenerator->MaybeRelativeToCurBinDir(ispcObj));
  }

  // Generate custom command rule files
  auto customCommands = this->GeneratorTarget->GetCustomCommands(this->GetConfigName());
  for (cmSourceFile const* sf : customCommands) {
    cmCustomCommandGenerator ccg(*sf->GetCustomCommand(), this->GetConfigName(), this->LocalGenerator);
    this->GenerateCustomRuleFile(ccg);
    if (this->Makefile->GetProperty("CLEAN_NO_CUSTOM").IsOff()) {
      std::vector<std::string> const& outputs = ccg.GetOutputs();
      for (std::string const& output : outputs) {
        this->CleanFiles.insert(this->LocalGenerator->MaybeRelativeToCurBinDir(output));
      }
      std::vector<std::string> const& byproducts = ccg.GetByproducts();
      for (std::string const& byproduct : byproducts) {
        this->CleanFiles.insert(this->LocalGenerator->MaybeRelativeToCurBinDir(byproduct));
      }
    }
  }

  // Construct codegen target
  {
    std::string const codegenTarget = this->LocalGenerator->GetRelativeTargetDirectory(this->GeneratorTarget) + "/codegen";
    this->LocalGenerator->WriteMakeRule(*this->BuildFileStream, nullptr, codegenTarget, {}, {}, true);
  }

  // Add byproducts from build events to the clean rules
  if (this->Makefile->GetProperty("CLEAN_NO_CUSTOM").IsOff()) {
    auto buildEventCommands = this->GeneratorTarget->GetPreBuildCommands();
    cm::append(buildEventCommands, this->GeneratorTarget->GetPreLinkCommands());
    cm::append(buildEventCommands, this->GeneratorTarget->GetPostBuildCommands());
    for (auto const& be : buildEventCommands) {
      cmCustomCommandGenerator beg(be, this->GetConfigName(), this->LocalGenerator);
      std::vector<std::string> const& byproducts = beg.GetByproducts();
      for (std::string const& byproduct : byproducts) {
        this->CleanFiles.insert(this->LocalGenerator->MaybeRelativeToCurBinDir(byproduct));
      }
    }
  }
}
```

This version of the function is slightly more concise and easier to read, while still maintaining the same functionality and edge cases as the original.

